// === Tab: arrow.js ===
class Arrow {
	constructor(pos, length, angle) {
		this.pos = pos;
		this.length = length;
		this.angle = angle;
		this.arrowData = [{
				pos: createVector(0, 0),
				"angle": PI / 5
			},
			{
				pos: createVector(0, 0),
				"angle": -PI / 5
			},
			{
				pos: createVector(this.length, 0),
				"angle": PI * 4 / 5
			},
			{
				pos: createVector(this.length, 0),
				"angle": -PI * 4 / 5
			}
		];
		this.lineData = [{
			"t": 1 / 10,
			"l": 1 / 24
		}, {
			"t": 1 / 12,
			"l": 1 / 32
		}, {
			"t": 1 / 16,
			"l": 1 / 48
		}];
	}

	buildArrow() {
		push()
		translate(this.pos.x, this.pos.y);
		rotate(this.angle)
		for (let d of this.arrowData) {
			let t = d.pos;
			let angle = d.angle;
			push()
			translate(t.x, t.y);
			rotate(angle);
			line(0, 0, this.length / 20, 0); // 16
			pop()
		}

		// add lines at either end of arrow
		this.addLines(createVector(0, 0), 0)
		line(0, 0, this.length, 0)
		this.addLines(createVector(this.length, 0), PI)
		pop()
	}

	addLines(v, angle) {
		push()
		translate(v.x, v.y)
		rotate(angle)
		for (let d of this.lineData) {
			let t = d.t * this.length;
			let l = d.l * this.length;
			push()
			translate(t, 0)
			rotate(PI * 1 / 2)
			line(-l, 0, l, 0);
			pop()
		}
		pop()
	}
}

// === Tab: circles.js ===
class Circles {
	constructor(pos, r, cr, angle, h) {
		this.pos = pos;
		this.r = r;
		this.cr = cr;
		this.angle = angle;
		this.h = h;
	}

	addCircle() {
		push()
		translate(this.pos.x, this.pos.y);
		let x = this.r * cos(this.angle);
		let y = this.r * sin(this.angle);
		fill(this.h, 100, 100)
		noStroke()
		//stroke(this.h, 100, 100)
		circle(x, y, this.cr);
		pop()
	}

}

