class Symbol1 {
	constructor(pos, length, i, j, n) {
		this.pos = pos;
		this.length = length;
		this.i = i;
		this.j = j;
		this.n = n;
		this.angles = [-PI / 4, PI / 4, PI * 3 / 4, -PI * 3 / 4];
		this.lineAngles = [PI / 4, PI * 3 / 4, -PI / 4, -PI * 3 / 4];
		this.t1 = createVector((this.i / this.n) * width, height * (this.j / this.n));
		this.t2 = createVector(((this.i) / this.n) * width, height * (this.j) / this.n);
		this.arrows = [];
		this.lines = [];
		this.circles = [];
		this.constructSymbol(n);
		this.show();
	}

	addArrows(angle1, angle2) {
		this.arrows.push(new Arrow(createVector(this.pos.x - this.length / 2, this.pos.y), this.length, angle1));
		this.arrows.push(new Arrow(createVector(this.pos.x, this.pos.y - this.length / 2), this.length, angle2));
	}

	addCircles(n) {
		noFill()
		push()
		translate(this.pos.x, this.pos.y);
		for (let a = 0; a < TWO_PI; a += TWO_PI / n) {
			let x = (this.length * 0.3) * cos(a);
			let y = (this.length * 0.3) * sin(a);
			circle(x, y, (this.length * 0.4));
		}
		pop()
	}

	constructSymbol(n) {
		let h = int(random(360));
		this.addArrows(0, PI / 2)
		let ll = width * 0.14;
		let lr = width * 0.04;
		let cl = (width * 0.15);
		let cr = (width * 0.05);
		for (let a of this.angles) {
			this.lines.push(new Diamond(this.pos, ll / (2 * this.n), lr, a));
			this.circles.push(new Circles(this.pos, cl / (this.n), cr / this.n, a, h));
			this.circles.push(new Circles(this.pos, cl / (this.n) + cr / 6, cr / (2 * this.n), a, h));
			this.circles.push(new Circles(this.pos, cl / (this.n) + cr / 4, cr / (4 * this.n), a, h));
		}
	}

	show() {
		let h = int(random(360));
		stroke(h, 100, 100)
		let n = (Math.random() * 3 | 0) * 4;
		if (n != 0) {
			this.addCircles(n)
		}
		for (let c of this.circles) {
			c.addCircle()
		}
		for (let l of this.lines) {
			l.addLine()
		}
		for (let a of this.arrows) {
			a.buildArrow()
		}
	}

}

