		noFill()
		let h = int(random(360));
		stroke(h, 100, 100)
		strokeWeight(2)
		push()
		translate(this.pos.x, this.pos.y);
		beginShape();
		for (let theta = 0; theta < TWO_PI; theta += 0.05) {
			let x = r * a * pow(cos(theta), 3);
			let y = r * b * pow(sin(theta), 3);
			vertex(x, y);
		}
		endShape(CLOSE);
		pop()
	}

