			let y = r * (2 * sin(theta) - sin(2 * theta)) / 3;
			vertex(x, y);
		}
		endShape(CLOSE);
		let circleRadii = [r * 0.1, r * 0.3, r * 0.5];
		for (let r of circleRadii) {
			circle(0, 0, r);
		}
		push()
		fill(0);
		strokeWeight(1)
		for (let i = 0; i < 3; i++) {
			let theta = i * TWO_PI / 3;
			let x = r * cos(theta);
			let y = r * sin(theta);
			for (let r of [...circleRadii].reverse()) {
				circle(x, y, r);
			}
		}
		pop()
		pop()
	}

