		noFill()
		stroke(h, 100, 100)
		strokeWeight(1)
		push()
		translate(this.pos.x, this.pos.y)
		beginShape()
		for (let theta = 0; theta < TWO_PI; theta += 0.05) {
			let na = 2 / m;
			let x = r * pow(abs(cos(theta)), na) * a * this.sgn(cos(theta));
			let y = r * pow(abs(sin(theta)), na) * b * this.sgn(sin(theta));
			vertex(x, y);
		}
		endShape(CLOSE)
		pop()
	}

	tearDrop(v, r, n = 4, a, h = 200) {
		noFill()
		stroke(h, 100, 100)
		strokeWeight(1)
		push()
		translate(this.pos.x + v.x * 1.2, this.pos.y + v.y * 1.2)
		rotate(a)
		beginShape()
		for (let theta = 0; theta < TWO_PI; theta += 0.1) {
			let x = r / 4 * cos(theta);
			let y = r / 4 * sin(theta) * pow(sin(theta / 2), n);
			vertex(x, y);
		}
		endShape(CLOSE)
		pop()
	}

	addInsideArc(v, a, r, n) {
		push()
		strokeWeight(1)
		translate(v.x, v.y)
		rotate(a + PI / 2)
		let arcRadii = [r / 6, r / 4, r / 3];
		for (let r of arcRadii) {
			arc(0, 0, r, r, PI / n, PI * (n - 1) / n);
		}
		pop()
	}

	addOutsideArc(v, a, r, n) {
		push()
		strokeWeight(1)
		translate(v.x, v.y)
		rotate(a + PI / 2)
		let arcRadii = [r / 6, r / 4, r / 3];
		for (let r of arcRadii) {
			arc(0, 0, r, r, PI * (n - 1) / n, PI / n);
		}
