// === Tab: mySketch.js ===
let symbols = [];
let nrows = 8;
let ncols = 12;

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(10, 10, 15);
	colorMode(HSB);
	noFill()

	for (let i = 0; i < ncols; i++) {
		for (let j = 0; j < nrows; j++) {
			// grid spacing based on width and height
			let x = width * (i + 0.5) / ncols; // centers in each col
			let y = height * (j + 0.5) / nrows; // centers in each row
			let cellSize = min(width / ncols, height / nrows);
			let r = random(1);
			if (r < 0.5) {
				symbols.push(new Symbol1(createVector(x, y), cellSize, i, j + 0.5, min(nrows, ncols)));
			} else if (r >= 0.5 && r < 0.9) {
				symbols.push(new Symbol2(createVector(x, y), cellSize));
			} else {
				symbols.push(new Symbol3(createVector(x, y), cellSize));
			}
		}
	}
}

function mousePressed() {
	setup()
}

